class Solution {
public:
    int minMoves(std::vector<std::string>& classroom, int energy) {
        int m = classroom.size(), n = classroom[0].size();
        int sr = 0, sc = 0;
        std::vector<std::pair<int, int>> litter;

        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (classroom[r][c] == 'S') {
                    sr = r; sc = c;
                } else if (classroom[r][c] == 'L') {
                    litter.push_back({r, c});
                }
            }
        }

        int k = litter.size();
        int init_mask = (1 << k) - 1;

        // State: (r, c, energy, mask)
        std::queue<std::tuple<int, int, int, int>> q;
        q.push({sr, sc, energy, init_mask});

        // Visited tracking using boolean 4D array or flattened array
        int visited[21][21][51][1024];
        std::memset(visited, 0, sizeof(visited));
        visited[sr][sc][energy][init_mask] = 1;

        int moves = 0;
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!q.empty()) {
            int sz = q.size();
            for (int step = 0; step < sz; ++step) {
                auto [r, c, ce, mask] = q.front();
                q.pop();

                if (mask == 0) return moves;
                if (ce == 0) continue;

                for (int d = 0; d < 4; ++d) {
                    int nr = r + dirs[d][0], nc = c + dirs[d][1];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && classroom[nr][nc] != 'X') {
                        int ne = (classroom[nr][nc] == 'R') ? energy : ce - 1;
                        int nm = mask;
                        if (classroom[nr][nc] == 'L') {
                            for (int i = 0; i < k; ++i) {
                                if (litter[i].first == nr && litter[i].second == nc) {
                                    nm &= ~(1 << i);
                                    break;
                                }
                            }
                        }
                        if (nr < 21 && nc < 21 && ne < 51 && nm < 1024 && !visited[nr][nc][ne][nm]) {
                            visited[nr][nc][ne][nm] = 1;
                            q.push({nr, nc, ne, nm});
                        }
                    }
                }
            }
            moves++;
        }

        return -1;
    }
};

import java.util.*;

class Solution {
    public int minMoves(String[] classroom, int energy) {
        int m = classroom.length, n = classroom[0].length();
        int sr = 0, sc = 0;
        List<int[]> litter = new ArrayList<>();

        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                char ch = classroom[r].charAt(c);
                if (ch == 'S') {
                    sr = r; sc = c;
                } else if (ch == 'L') {
                    litter.add(new int[]{r, c});
                }
            }
        }

        int k = litter.size();
        int initMask = (1 << k) - 1;

        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{sr, sc, energy, initMask});

        boolean[][][][] visited = new boolean[m][n][energy + 1][1 << k];
        visited[sr][sc][energy][initMask] = true;

        int moves = 0;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!q.isEmpty()) {
            int sz = q.size();
            for (int step = 0; step < sz; ++step) {
                int[] curr = q.poll();
                int r = curr[0], c = curr[1], ce = curr[2], mask = curr[3];

                if (mask == 0) return moves;
                if (ce == 0) continue;

                for (int[] dir : dirs) {
                    int nr = r + dir[0], nc = c + dir[1];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && classroom[nr].charAt(nc) != 'X') {
                        char ch = classroom[nr].charAt(nc);
                        int ne = (ch == 'R') ? energy : ce - 1;
                        int nm = mask;
                        if (ch == 'L') {
                            for (int i = 0; i < k; ++i) {
                                if (litter.get(i)[0] == nr && litter.get(i)[1] == nc) {
                                    nm &= ~(1 << i);
                                    break;
                                }
                            }
                        }
                        if (!visited[nr][nc][ne][nm]) {
                            visited[nr][nc][ne][nm] = true;
                            q.offer(new int[]{nr, nc, ne, nm});
                        }
                    }
                }
            }
            moves++;
        }

        return -1;
    }
}

