var minMoves = function(classroom, energy) {
    const m = classroom.length, n = classroom[0].length;
    let sr = 0, sc = 0;
    const litter = [];

    for (let r = 0; r < m; ++r) {
        for (let c = 0; c < n; ++c) {
            const ch = classroom[r][c];
            if (ch === 'S') {
                sr = r; sc = c;
            } else if (ch === 'L') {
                litter.push([r, c]);
            }
        }
    }

    const k = litter.size || litter.length;
    const initMask = (1 << k) - 1;

    const q = [[sr, sc, energy, initMask]];
    const visited = new Set();
    visited.add(`${sr},${sc},${energy},${initMask}`);

    let moves = 0;
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    while (q.length > 0) {
        const sz = q.length;
        for (let step = 0; step < sz; ++step) {
            const [r, c, ce, mask] = q.shift();

            if (mask === 0) return moves;
            if (ce === 0) continue;

            for (const [dr, dc] of dirs) {
                const nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && classroom[nr][nc] !== 'X') {
                    const ch = classroom[nr][nc];
                    const ne = ch === 'R' ? energy : ce - 1;
                    let nm = mask;
                    if (ch === 'L') {
                        for (let i = 0; i < k; ++i) {
                            if (litter[i][0] === nr && litter[i][1] === nc) {
                                nm &= ~(1 << i);
                                break;
                            }
                        }
                    }
                    const key = `${nr},${nc},${ne},${nm}`;
                    if (!visited.has(key)) {
                        visited.add(key);
                        q.push([nr, nc, ne, nm]);
                    }
                }
            }
        }
        moves++;
    }

    return -1;
};
